-- Урок 13: Настройка промптов
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 13, 1, 'Что такое системный промпт?', '["Команда для запуска бота", "Базовая инструкция, определяющая стиль и роль нейросети", "Текст приветствия для пользователя", "Название файла с настройками"]', '[2]', '{"1": "Неверно. Системный промпт — это не команда запуска, а инструкция для нейросети.", "2": "✅ Правильно! Системный промпт задает базовое поведение нейросети: её роль, стиль общения и ограничения.", "3": "Неверно. Приветствие — это сообщение пользователю, а системный промпт настраивает нейросеть.", "4": "Неверно. Промпт — это текстовая инструкция, а не название файла."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 13, 2, 'Зачем настраивать температуру (temperature) в запросах к нейросети?', '["Для контроля скорости ответа", "Для управления креативностью и случайностью ответов", "Для экономии токенов", "Для изменения языка ответа"]', '[2]', '{"1": "Неверно. Температура не влияет на скорость, она управляет вариативностью ответов.", "2": "✅ Правильно! Низкая температура (0.1-0.3) делает ответы предсказуемыми, высокая (0.7-1.0) — креативными.", "3": "Неверно. Температура влияет на стиль ответа, но не экономит токены.", "4": "Неверно. Язык указывается в промпте, температура управляет креативностью."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 13, 3, 'Как тестировать качество промптов?', '["Один раз запустить и проверить", "Тестировать на разных примерах и сравнивать результаты", "Просто довериться нейросети", "Использовать самый длинный промпт"]', '[2]', '{"1": "Неверно. Один тест не покажет качество — нужны разные сценарии.", "2": "✅ Правильно! Тестирование на разных кейсах помогает найти слабые места и улучшить промпт.", "3": "Неверно. Нейросеть работает по инструкциям, их нужно проверять и улучшать.", "4": "Неверно. Длина не гарантирует качество — важна точность и структура промпта."}', 0);

-- Урок 14: Работа с документами
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 14, 1, 'Какие форматы документов может обрабатывать бот?', '["Только TXT", "TXT, PDF, DOCX и другие текстовые форматы", "Только изображения", "Только видео файлы"]', '[2]', '{"1": "Неверно. Современные боты поддерживают множество форматов, не только TXT.", "2": "✅ Правильно! Бот может извлекать текст из PDF, DOCX, TXT и других документов для обработки.", "3": "Неверно. Хотя изображения возможны, текстовые документы — основная задача.", "4": "Неверно. Видео — сложный формат, чаще используются текстовые файлы."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 14, 2, 'Зачем извлекать текст из PDF перед отправкой нейросети?', '["Чтобы нейросеть могла обработать содержимое", "Для красоты", "PDF уже понятен нейросети", "Это не нужно"]', '[1]', '{"1": "✅ Правильно! Нейросеть работает с текстом, поэтому PDF нужно конвертировать в читаемый формат.", "2": "Неверно. Извлечение текста критически важно для работы, а не для эстетики.", "3": "Неверно. Нейросеть не понимает формат PDF напрямую, нужен текст.", "4": "Неверно. Без извлечения текста нейросеть не сможет обработать документ."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 14, 3, 'Какая библиотека используется для работы с DOCX в Python?', '["pdfplumber", "python-docx", "pillow", "requests"]', '[2]', '{"1": "Неверно. pdfplumber — для PDF файлов, а не для DOCX.", "2": "✅ Правильно! python-docx — стандартная библиотека для чтения и создания Word документов.", "3": "Неверно. Pillow — для работы с изображениями, не с документами.", "4": "Неверно. requests — для HTTP запросов, не для обработки документов."}', 0);

-- Урок 15: База знаний и RAG
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 15, 1, 'Что такое RAG (Retrieval-Augmented Generation)?', '["Способ шифрования данных", "Метод поиска релевантной информации перед генерацией ответа", "Тип нейросети", "База данных"]', '[2]', '{"1": "Неверно. RAG — не про шифрование, а про улучшение качества ответов через поиск.", "2": "✅ Правильно! RAG находит релевантные документы в базе знаний и использует их для точного ответа.", "3": "Неверно. RAG — это техника работы с данными, а не отдельная нейросеть.", "4": "Неверно. RAG использует базу знаний, но сам является методологией, а не БД."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 15, 2, 'Зачем нужны векторные представления (embeddings)?', '["Для хранения паролей", "Для поиска семантически похожих текстов", "Для ускорения интернета", "Для создания изображений"]', '[2]', '{"1": "Неверно. Embeddings не связаны с безопасностью, они для поиска похожих текстов.", "2": "✅ Правильно! Embeddings превращают текст в числа, позволяя находить похожие по смыслу документы.", "3": "Неверно. Embeddings работают с текстом, не влияют на скорость интернета.", "4": "Неверно. Embeddings — для текстового поиска, не для генерации изображений."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 15, 3, 'Какая библиотека используется для векторного поиска?', '["FAISS", "NumPy", "Pandas", "Flask"]', '[1]', '{"1": "✅ Правильно! FAISS от Facebook — эффективная библиотека для поиска похожих векторов.", "2": "Неверно. NumPy — для математических операций, а не для векторного поиска.", "3": "Неверно. Pandas — для работы с таблицами, не для поиска векторов.", "4": "Неверно. Flask — веб-фреймворк, не инструмент для векторного поиска."}', 0);

-- Урок 16: Гибридный поиск
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 16, 1, 'Что такое ререйкинг (reranking)?', '["Удаление старых данных", "Повторная сортировка результатов поиска для повышения точности", "Создание новой базы данных", "Перезапуск бота"]', '[2]', '{"1": "Неверно. Ререйкинг не удаляет данные, а улучшает качество поиска.", "2": "✅ Правильно! Ререйкинг пересортировывает найденные документы, ставя самые релевантные на первые места.", "3": "Неверно. Ререйкинг работает с существующими результатами, не создает БД.", "4": "Неверно. Ререйкинг — это метод улучшения поиска, а не перезапуск системы."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 16, 2, 'Зачем использовать гибридный поиск (FAISS + BM25)?', '["Для красоты кода", "Для объединения преимуществ векторного и ключевого поиска", "Это обязательное требование", "Для экономии памяти"]', '[2]', '{"1": "Неверно. Гибридный поиск критически важен для точности, а не для эстетики.", "2": "✅ Правильно! FAISS находит семантически похожие тексты, BM25 — точные совпадения ключевых слов. Вместе — максимальная точность.", "3": "Неверно. Гибридный поиск — не обязателен, но сильно повышает качество.", "4": "Неверно. Гибридный поиск улучшает точность, но не экономит память."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (3, 16, 3, 'Как измерить точность ответов бота?', '["Просто угадать", "Тестировать на наборе вопросов с известными правильными ответами", "Спросить у друзей", "Это невозможно измерить"]', '[2]', '{"1": "Неверно. Точность нужно измерять объективно, а не угадывать.", "2": "✅ Правильно! Тестовый набор (test set) с правильными ответами позволяет оценить качество системы.", "3": "Неверно. Нужны систематические тесты, а не субъективные мнения.", "4": "Неверно. Точность измеряется через метрики и тестирование."}', 0);

-- ============================================================================
-- МОДУЛЬ 4 - Деплой и Production (4 урока × 3 теста = 12 тестов)
-- ============================================================================

-- Урок 17: Логирование и мониторинг
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 17, 1, 'Зачем нужно логирование в боте?', '["Только для красоты", "Для отслеживания ошибок и мониторинга работы", "Это замедляет бота", "Логирование не нужно"]', '[2]', '{"1": "Неверно. Логирование критически важно для диагностики, а не для эстетики.", "2": "✅ Правильно! Логи помогают находить ошибки, отслеживать использование и улучшать систему.", "3": "Неверно. Правильное логирование почти не влияет на производительность.", "4": "Неверно. Без логов невозможно понять, что происходит с ботом в production."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 17, 2, 'Какие уровни логирования существуют?', '["Только ERROR", "DEBUG, INFO, WARNING, ERROR, CRITICAL", "Только INFO", "Логирование без уровней"]', '[2]', '{"1": "Неверно. Существует несколько уровней для разных ситуаций.", "2": "✅ Правильно! DEBUG — детальная отладка, INFO — общая информация, WARNING — предупреждения, ERROR — ошибки, CRITICAL — критические сбои.", "3": "Неверно. INFO — только один из уровней, есть и другие.", "4": "Неверно. Уровни помогают фильтровать логи по важности."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 17, 3, 'Что такое мониторинг работы бота?', '["Просмотр кода", "Отслеживание метрик: количество запросов, ошибки, время ответа", "Чтение документации", "Перезапуск сервера"]', '[2]', '{"1": "Неверно. Просмотр кода — это разработка, а не мониторинг работающей системы.", "2": "✅ Правильно! Мониторинг показывает, как работает бот в реальном времени: нагрузка, ошибки, производительность.", "3": "Неверно. Документация помогает разобраться в системе, но не показывает текущее состояние.", "4": "Неверно. Перезапуск — это действие, а мониторинг — наблюдение за работой."}', 0);

-- Урок 18: Подготовка к деплою
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 18, 1, 'Что такое деплой (deployment)?', '["Удаление кода", "Размещение приложения на сервере для постоянной работы", "Написание документации", "Тестирование локально"]', '[2]', '{"1": "Неверно. Деплой — это публикация, а не удаление.", "2": "✅ Правильно! Деплой переносит бота с вашего компьютера на сервер, где он работает 24/7.", "3": "Неверно. Документация полезна, но деплой — это размещение на сервере.", "4": "Неверно. Локальное тестирование — до деплоя, а деплой — это публикация."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 18, 2, 'Какие платформы можно использовать для деплоя бота?', '["Только свой компьютер", "VPS серверы, облачные платформы (AWS, Heroku, Amvera)", "Только блокнот", "Деплой невозможен"]', '[2]', '{"1": "Неверно. Компьютер подходит для разработки, но для production нужен сервер.", "2": "✅ Правильно! VPS (DigitalOcean, AWS EC2), PaaS (Heroku, Amvera) — популярные решения для деплоя.", "3": "Неверно. Блокнот — для написания кода, не для размещения бота.", "4": "Неверно. Деплой — стандартный процесс публикации приложений."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 18, 3, 'Зачем нужны переменные окружения (.env)?', '["Для ускорения кода", "Для безопасного хранения секретных данных (токенов, API ключей)", "Для изменения цвета интерфейса", "Это не нужно"]', '[2]', '{"1": "Неверно. Переменные окружения не влияют на скорость выполнения.", "2": "✅ Правильно! .env файл хранит секреты (токены, ключи) отдельно от кода, повышая безопасность.", "3": "Неверно. Интерфейс настраивается в коде бота, а .env для секретных данных.", "4": "Неверно. Без .env секреты окажутся в коде, что небезопасно."}', 0);

-- Урок 19: Деплой на сервер
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 19, 1, 'Что такое zero-downtime deployment?', '["Полная остановка системы", "Обновление без остановки работы бота", "Удаление всех данных", "Создание новой базы"]', '[2]', '{"1": "Неверно. Zero-downtime означает ОТСУТСТВИЕ простоя, а не полную остановку.", "2": "✅ Правильно! Zero-downtime deployment позволяет обновлять бота без прерывания обслуживания пользователей.", "3": "Неверно. При обновлении данные сохраняются, удаление не требуется.", "4": "Неверно. База остается, обновляется только код приложения."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 19, 2, 'Как обновить бота без остановки?', '["Просто выключить и включить", "Использовать Blue-Green deployment или Rolling updates", "Удалить старую версию", "Переписать весь код"]', '[2]', '{"1": "Неверно. Выключение и включение создает простой — это не zero-downtime.", "2": "✅ Правильно! Blue-Green (две версии) или Rolling updates (постепенная замена) обеспечивают непрерывность работы.", "3": "Неверно. Удаление старой версии без подготовки приведет к простою.", "4": "Неверно. Переписывание кода — это разработка, а не стратегия обновления."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 19, 3, 'Зачем нужен откат (rollback)?', '["Для ускорения работы", "Чтобы вернуться к предыдущей версии при проблемах", "Для добавления новых функций", "Это не нужно"]', '[2]', '{"1": "Неверно. Откат не ускоряет работу, он восстанавливает стабильность.", "2": "✅ Правильно! Если новая версия содержит ошибки, откат быстро восстанавливает работу старой версии.", "3": "Неверно. Новые функции добавляются через обновления, откат возвращает назад.", "4": "Неверно. Откат — критически важный механизм безопасности при обновлениях."}', 0);

-- Урок 20: Обновление и масштабирование
INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 20, 1, 'Что такое горизонтальное масштабирование?', '["Увеличение мощности одного сервера", "Добавление большего количества серверов", "Удаление старых серверов", "Уменьшение нагрузки"]', '[2]', '{"1": "Неверно. Увеличение мощности одного сервера — это вертикальное масштабирование.", "2": "✅ Правильно! Горизонтальное масштабирование добавляет больше серверов для распределения нагрузки.", "3": "Неверно. Удаление серверов уменьшает мощность, а не масштабирует систему.", "4": "Неверно. Масштабирование увеличивает возможности системы, а не уменьшает нагрузку."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 20, 2, 'Зачем нужен балансировщик нагрузки (load balancer)?', '["Для написания кода", "Для равномерного распределения запросов между серверами", "Для хранения данных", "Для создания интерфейса"]', '[2]', '{"1": "Неверно. Балансировщик работает с запросами, не с кодом.", "2": "✅ Правильно! Load balancer распределяет запросы на несколько серверов, предотвращая перегрузку одного.", "3": "Неверно. Данные хранит база данных, а балансировщик распределяет трафик.", "4": "Неверно. Интерфейс создается в коде бота, балансировщик управляет нагрузкой."}', 0);

INSERT INTO tests (module_no, lesson_no, question_number, question_text, options, correct_answers, explanations, is_multiple_choice)
VALUES (4, 20, 3, 'Какие метрики важны для оптимизации?', '["Только цвет интерфейса", "Время ответа, использование памяти, количество ошибок", "Только размер кода", "Метрики не нужны"]', '[2]', '{"1": "Неверно. Цвет не влияет на производительность системы.", "2": "✅ Правильно! Время ответа показывает скорость, память — эффективность, ошибки — стабильность.", "3": "Неверно. Размер кода важен, но не основная метрика для оптимизации работы.", "4": "Неверно. Без метрик невозможно понять, где оптимизировать систему."}', 0);
